package com.nexus.access.backend.auth; import jakarta.validation.constraints.*; public record RegisterRequest(@NotBlank @Size(max=100) String firstName,@NotBlank @Size(max=100) String lastName,@NotBlank @Email @Size(max=255) String email,@NotBlank @Size(min=12,max=128) @Pattern(regexp="(?=.*[A-Z])(?=.*[a-z])(?=.*\\d).*",message="must include uppercase, lowercase and a digit") String password){}
